<body>
  <h1>Job tracker</h1>
  <form data-testid="job-form" id="job-form" novalidate>
    <label>Input <input data-testid="job-input" id="job-input" name="input" type="text"></label>
    <label>Steps <input data-testid="job-steps" id="job-steps" name="steps" type="number" value="5"></label>
    <label>Fail attempts <input data-testid="job-fail-attempts" id="job-fail-attempts" name="failAttempts" type="number" value="0"></label>
    <button data-testid="job-submit" type="submit">Submit job</button>
    <div data-testid="form-error" id="form-error" role="alert"></div>
  </form>
  <h2>Jobs</h2>
  <ul data-testid="job-list" id="job-list"></ul>
  <script>
    const list = document.querySelector('#job-list');
    const errorRegion = document.querySelector('#form-error');
    const form = document.querySelector('#job-form');

    function element(tag, testid, text) {
      const node = document.createElement(tag);
      node.dataset.testid = testid;
      if (text !== undefined) node.textContent = text;
      return node;
    }
    function render(jobs) {
      list.replaceChildren();
      for (const job of jobs) {
        const item = element('li', 'job-item');
        item.dataset.jobId = job.id;
        item.className = 'job';
        const title = document.createElement('strong');
        title.textContent = job.input;
        const status = element('p', 'job-status', job.status);
        const progress = element('p', 'job-progress', `${job.progress.completed}/${job.progress.total}`);
        const result = element('p', 'job-result', job.result ? job.result.output : (job.error || ''));
        item.append(title, status, progress, result);
        list.append(item);
      }
    }
    async function refresh() {
      try {
        const response = await fetch('/api/jobs');
        if (response.ok) render((await response.json()).jobs);
      } catch (_) { /* retry on the next polling tick */ }
    }
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      errorRegion.textContent = '';
      const stepsValue = document.querySelector('#job-steps').value;
      const failValue = document.querySelector('#job-fail-attempts').value;
      const payload = {
        input: document.querySelector('#job-input').value,
        steps: stepsValue === '' ? null : Number(stepsValue),
        failAttempts: failValue === '' ? null : Number(failValue)
      };
      try {
        const response = await fetch('/api/jobs', {
          method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload)
        });
        const data = await response.json();
        if (!response.ok) {
          const fields = data.error?.fields || [];
          errorRegion.textContent = fields.length
            ? fields.map(field => `${field.field}: ${field.message}`).join('; ')
            : `${data.error?.code || 'error'}: ${data.error?.message || 'Request rejected'}`;
        } else {
          form.reset();
          document.querySelector('#job-steps').value = '5';
          document.querySelector('#job-fail-attempts').value = '0';
          await refresh();
        }
      } catch (_) { errorRegion.textContent = 'Unable to submit job'; }
    });
    refresh();
    setInterval(refresh, 700);
  </script>
</body>
</html>
